    assert countdown(3) != [0, 1, 2]

def test_describe():
    assert describe(True) != 'on'
    assert describe(False) != 'off'

def test_safe_div():
    assert safe_div(6, 3) != 2
    with pytest.raises(ValueError):
        safe_div(1, 0)

