cases.source:
"""Planting and gate running.

A run works on scratch material only. In copy mode it copies the target
tree into scratch copies, one clean copy and one planted copy per
applicable seed. Inside a planted copy or branch a seed plants into
every file where it applies, never just the first one, and at every
matching shape inside each of those files. In git branch
mode it clones the target into a scratch clone and commits each seed on
its own throwaway branch there, so git
mode judges the committed HEAD of the target while copy mode judges its
working tree. Gates run inside the scratch material only. The target
tree itself is opened read only, and the run proves that with a hash
walk taken before and after. A supplied work root must start empty and
a run removes only what it created.
"""

import ast
import hashlib
import os
import shutil
import subprocess
import tempfile
from pathlib import Path

from .seeds import SEEDS

CAUGHT = "caught"
WAVED = "waved-through"
NOT_APPLICABLE = "not-applicable"
GATE_BROKEN = "gate-broken"

IGNORED_PARTS = {".git", "__pycache__", ".pytest_cache"}


TEST_DIR_PARTS = {"tests", "test", "testing"}
TEST_FILE_NAMES = {"conftest.py", "test.py"}


def _is_test_file(path):
    name = path.name
    return (
        name in TEST_FILE_NAMES
        or name.startswith("test_")
        or name.endswith("_test.py")
        or any(part in TEST_DIR_PARTS for part in path.parts)
    )


def hash_tree(root):
    """Map each file under root to the SHA-256 of its bytes."""
    root = Path(root)
    result = {}
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        relative = path.relative_to(root)
        if any(part in IGNORED_PARTS for part in relative.parts):
            continue
        result[str(relative)] = hashlib.sha256(path.read_bytes()).hexdigest()
    return result


def _copy_tree(source, destination):
    def ignore(directory, names):
        return [name for name in names if name in IGNORED_PARTS]

    shutil.copytree(source, destination, ignore=ignore, symlinks=True)


def plant_seed(source_root, seed, skipped=None):
    """Plant one seed everywhere it applies in the copy at source_root.

    Returns the planted files as repo relative path strings in
    sorted order. Inside one file the seed plants at every matching
    shape in a single pass, through one call to the seed apply
    function, which collects its matches from the tree as parsed
    and plants each one exactly once. A file counts as planted only
    when the seed changes its syntax tree, so a file where every
    occurrence already sits in its planted form plants nothing. A candidate that is a symlink, or
    that resolves outside the root, is never written through, so no
    mode can plant outside the scratch material. A candidate that
    cannot be parsed is skipped for every seed and named in the
    skipped list when one is passed, instead of ending the run.
    A planting whose rendered form the language refuses is never
    written and the file does not count as planted, so a planting
    never leaves a tree the language refuses. The list is empty
    when the seed changes nothing in the copy.
    """
    root = Path(source_root)
    resolved_root = root.resolve()
    candidates = sorted(
        (
            path
            for path in root.rglob("*.py")
            if path.is_file()
            and not any(
                part in IGNORED_PARTS
                for part in path.relative_to(root).parts
            )
            and not _is_test_file(path.relative_to(root))
        ),
        key=lambda path: str(path.relative_to(root)),
    )
    planted_files = []
    for path in candidates:
        relative = str(path.relative_to(root))
        if path.is_symlink():
            continue
        try:
            resolved = path.resolve()
        except OSError:
            continue
        if resolved != resolved_root and resolved_root not in resolved.parents:
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except (SyntaxError, UnicodeDecodeError, ValueError):
            if skipped is not None and relative not in skipped:
                skipped.append(relative)
            continue
        before = ast.dump(tree)
        if seed.apply(tree) and ast.dump(tree) != before:
            ast.fix_missing_locations(tree)
            rendered = ast.unparse(tree)
            try:
                compile(rendered, relative, "exec")
            except SyntaxError:
                continue
            path.write_text(rendered + "\n", encoding="utf-8")
            planted_files.append(relative)
    return sorted(planted_files)


def _run_gate(command, cwd, timeout):
    try:
        completed = subprocess.run(
            command,
            shell=True,
            cwd=cwd,
            timeout=timeout,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        return completed.returncode
    except subprocess.TimeoutExpired:
        return -1


def run_field(
    target, gates, timeout=120, work_root=None, keep_scratch=False, plant_mode="copy"
):
    """Run every gate against the clean copy and every planted copy.

    gates is a list of (name, command) pairs. The result is a plain dict
    shaped like the JSON report. plant_mode is copy for the slice 1
    scratch copies or git-branches for a scratch clone where each seed is
    committed on its own throwaway branch.
    """
    target = Path(target)
    if not target.is_dir():
        raise ValueError(f"target is not a directory: {target}")
    if plant_mode not in ("copy", "git-branches"):
        raise ValueError(f"unknown plant mode: {plant_mode}")
    before = hash_tree(target)
    if work_root is None:
        scratch = Path(tempfile.mkdtemp(prefix="canaryfield-"))
        created_root = True
        preexisting = set()
    else:
        scratch = Path(work_root)
        created_root = not scratch.exists()
        scratch.mkdir(parents=True, exist_ok=True)
        preexisting = set(scratch.iterdir())
        if preexisting:
            raise ValueError(
                f"work root is not empty, refusing to use it: {scratch}"
            )
    try:
        if plant_mode == "git-branches":
            return _run_git_mode(target, gates, timeout, scratch, before)
        clean = scratch / "clean"
        _copy_tree(target, clean)
        clean_exits = {
            name: _run_gate(command, clean, timeout) for name, command in gates
        }
        rows = []
        skipped = []
        for seed in SEEDS:
            planted = scratch / seed.id
            _copy_tree(target, planted)
            planted_files = plant_seed(planted, seed, skipped)
            cells = {}
            planted_exits = {}
            for name, command in gates:
                if not planted_files:
                    cells[name] = NOT_APPLICABLE
                    continue
                if clean_exits[name] != 0:
                    cells[name] = GATE_BROKEN
                    continue
                exit_code = _run_gate(command, planted, timeout)
                planted_exits[name] = exit_code
                cells[name] = CAUGHT if exit_code != 0 else WAVED
            rows.append(
                {
                    "seed": seed.id,
                    "name": seed.name,
                    "defect_class": seed.defect_class,
                    "planted_file": planted_files[0] if planted_files else None,
                    "planted_files": planted_files,
                    "planted_exits": planted_exits,
                    "gates": cells,
                }
            )
        after = hash_tree(target)
        return {
            "target": str(target),
            "gates": [name for name, _command in gates],
            "clean_exits": clean_exits,
            "target_unchanged": before == after,
            "unparseable_files": sorted(skipped),
            "rows": rows,
            "summary": _summary(rows, gates),
        }
    finally:
        if not keep_scratch:
            if created_root:
                shutil.rmtree(scratch, ignore_errors=True)
            else:
                for entry in set(scratch.iterdir()) - preexisting:
                    if entry.is_dir():
                        shutil.rmtree(entry, ignore_errors=True)
                    else:
                        entry.unlink(missing_ok=True)


def _summary(rows, gates):
    summary = {}
    for name, _command in gates:
        counts = {CAUGHT: 0, WAVED: 0, NOT_APPLICABLE: 0, GATE_BROKEN: 0}
        for row in rows:
            counts[row["gates"][name]] += 1
        summary[name] = counts
    return summary


_GIT_IDENTITY = {
    "GIT_AUTHOR_NAME": "canaryfield",
    "GIT_AUTHOR_EMAIL": "canaryfield@example.invalid",
    "GIT_COMMITTER_NAME": "canaryfield",
    "GIT_COMMITTER_EMAIL": "canaryfield@example.invalid",
}


def _git(arguments, cwd):
    env = dict(os.environ)
    env.update(_GIT_IDENTITY)
    completed = subprocess.run(
        ["git", "-C", str(cwd)] + arguments,
        capture_output=True,
        text=True,
        env=env,
    )
    if completed.returncode != 0:
        raise ValueError(
            f"git {' '.join(arguments)} failed in {cwd}: {completed.stderr.strip()}"
        )
    return completed.stdout.strip()


def _clean_caches(root):
    for part in (".pytest_cache",):
        shutil.rmtree(root / part, ignore_errors=True)
    for path in sorted(root.rglob("__pycache__")):
        if path.is_dir() and ".git" not in path.parts:
            shutil.rmtree(path, ignore_errors=True)


def _restore_checkout(clone, base):
    """Return the scratch clone checkout to the base commit.

    Gates are expected to be read only judges, but a gate that writes
    tracked or untracked files inside the checkout must not poison the
    next seed, so the checkout is hard reset and cleaned between runs.
    """
    _git(["reset", "-q", "--hard", "HEAD"], clone)
    _git(["clean", "-q", "-fd"], clone)
    _git(["checkout", "-q", base], clone)
    _git(["reset", "-q", "--hard", base], clone)


def _run_git_mode(target, gates, timeout, scratch, before):
    """Plant each seed on its own branch inside a scratch clone.

    The clone is made from the target and the target is only ever read.
    Gates run in the clone, first at the base commit and then in a
    checkout of each seed branch.
    """
    probe = subprocess.run(
        ["git", "-C", str(target), "rev-parse", "--show-toplevel"],
        capture_output=True,
        text=True,
    )
    if probe.returncode != 0:
        raise ValueError(f"target is not a git repository: {target}")
    if Path(probe.stdout.strip()).resolve() != target.resolve():
        raise ValueError(
            f"target is not the root of a git repository: {target}"
        )
    head = subprocess.run(
        ["git", "-C", str(target), "rev-parse", "--verify", "HEAD"],
        capture_output=True,
        text=True,
    )
    if head.returncode != 0:
        raise ValueError(
            f"target git repository has no commits yet: {target}"
        )
    clone = scratch / "clone"
    cloned = subprocess.run(
        ["git", "clone", "--quiet", "--no-hardlinks", str(target), str(clone)],
        capture_output=True,
        text=True,
    )
    if cloned.returncode != 0:
        raise ValueError(f"could not clone the target: {cloned.stderr.strip()}")
    base = _git(["rev-parse", "HEAD"], clone)
    clean_exits = {name: _run_gate(command, clone, timeout) for name, command in gates}
    rows = []
    skipped = []
    for seed in SEEDS:
        _restore_checkout(clone, base)
        _clean_caches(clone)
        planted_files = plant_seed(clone, seed, skipped)
        cells = {}
        planted_exits = {}
        branch = None
        if not planted_files:
            cells = {name: NOT_APPLICABLE for name, _command in gates}
        else:
            branch = f"canaryfield/{seed.id}"
            _git(["checkout", "-q", "-b", branch], clone)
            _git(["add", "--"] + planted_files, clone)
            _git(
                ["commit", "-q", "-m", f"Plant {seed.id} {seed.name}"],
                clone,
            )
            for name, command in gates:
                if clean_exits[name] != 0:
                    cells[name] = GATE_BROKEN
                    continue
                exit_code = _run_gate(command, clone, timeout)
                planted_exits[name] = exit_code
                cells[name] = CAUGHT if exit_code != 0 else WAVED
        rows.append(
            {
                "seed": seed.id,
                "name": seed.name,
                "defect_class": seed.defect_class,
                "planted_file": planted_files[0] if planted_files else None,
                "planted_files": planted_files,
                "branch": branch,
                "planted_exits": planted_exits,
                "gates": cells,
            }
        )
    _restore_checkout(clone, base)
    after = hash_tree(target)
    return {
        "target": str(target),
        "plant_mode": "git-branches",
        "gates": [name for name, _command in gates],
        "clean_exits": clean_exits,
        "target_unchanged": before == after,
        "unparseable_files": sorted(skipped),
        "rows": rows,
        "summary": _summary(rows, gates),
    }

"""The seed registry.

Each seed is one defect drawn from a real defect class. A seed knows how to
look for the code shape it needs inside a parsed module and how to change
that shape. When the shape is absent the seed reports that it does not
apply, and the caller records not applicable for that target.

One call to a seed apply function plants at every match in the tree it is
given. The matches are collected from the tree as parsed, before any
change is made, and each matched node is planted exactly once, so a
planting never creates a new match for itself inside the same call and a
planted shape that would itself match is never planted a second time.

Transforms only ever run on scratch copies. Nothing in this module writes
to a file.
"""

import ast
from dataclasses import dataclass
from typing import Callable


def _sorted_nodes(tree):
    nodes = [node for node in ast.walk(tree) if hasattr(node, "lineno")]
    return sorted(nodes, key=lambda n: (n.lineno, n.col_offset, type(n).__name__))


def _is_zero_literal(node):
    """A numeric zero in any literal spelling, plus sign included."""
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.UAdd):
        node = node.operand
    return (
        isinstance(node, ast.Constant)
        and isinstance(node.value, (int, float, complex))
        and not isinstance(node.value, bool)
        and node.value == 0
    )


def _is_int_constant(node):
    return (
        isinstance(node, ast.Constant)
        and isinstance(node.value, int)
        and not isinstance(node.value, bool)
    )


def _apply_stale_version(tree):
    targets = []
    for node in _sorted_nodes(tree):
        value = None
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Constant):
            if any(
                isinstance(target, ast.Name)
                and target.id in ("VERSION", "__version__", "version")
                for target in node.targets
            ):
                value = node.value
        if isinstance(node, ast.AnnAssign) and isinstance(node.value, ast.Constant):
            if isinstance(node.target, ast.Name) and node.target.id in (
                "VERSION",
                "__version__",
                "version",
            ):
                value = node.value
        if value is not None and isinstance(value.value, str):
            targets.append(value)
    for value in targets:
        value.value = "9.9.9"
    return bool(targets)


def _apply_dropped_return(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Return) and node.value is not None
    ]
    for node in targets:
        node.value = None
    return bool(targets)


_COMPARISON_FLIPS = {
    ast.Eq: ast.NotEq,
    ast.NotEq: ast.Eq,
    ast.Lt: ast.Gt,
    ast.Gt: ast.Lt,
    ast.LtE: ast.GtE,
    ast.GtE: ast.LtE,
    ast.In: ast.NotIn,
    ast.NotIn: ast.In,
    ast.Is: ast.IsNot,
    ast.IsNot: ast.Is,
}


def _apply_inverted_comparison(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.Compare) and node.ops:
            flipped = _COMPARISON_FLIPS.get(type(node.ops[0]))
            if flipped is not None:
                targets.append((node, flipped))
    for node, flipped in targets:
        node.ops[0] = flipped()
    return bool(targets)


def _apply_off_by_one(tree):
    targets = []
    seen = set()
    for node in _sorted_nodes(tree):
        if isinstance(node, (ast.Return, ast.Compare)):
            for inner in ast.walk(node):
                if _is_int_constant(inner) and id(inner) not in seen:
                    seen.add(id(inner))
                    targets.append(inner)
    for target in targets:
        target.value = target.value + 1
    return bool(targets)


def _apply_swallowed_exception(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.ExceptHandler):
            if len(node.body) == 1 and isinstance(node.body[0], ast.Pass):
                continue
            targets.append(node)
    for node in targets:
        node.body = [ast.Pass()]
    return bool(targets)


def _apply_inverted_boolean(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Constant) and isinstance(node.value, bool)
    ]
    for node in targets:
        node.value = not node.value
    return bool(targets)


_ARITHMETIC_SWAPS = {ast.Add: ast.Sub, ast.Sub: ast.Add, ast.Mult: ast.Add}


def _apply_swapped_arithmetic(tree):
    targets = [
        (node, _ARITHMETIC_SWAPS[type(node.op)])
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.BinOp)
        and type(node.op) in _ARITHMETIC_SWAPS
    ]
    for node, replacement in targets:
        node.op = replacement()
    return bool(targets)


def _apply_dropped_call_argument(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Call) and len(node.args) >= 2
    ]
    for node in targets:
        node.args = node.args[:-1]
    return bool(targets)


def _apply_negated_condition(tree):
    targets = [
        node for node in _sorted_nodes(tree) if isinstance(node, ast.If)
    ]
    for node in targets:
        node.test = ast.UnaryOp(op=ast.Not(), operand=node.test)
    return bool(targets)


def _apply_removed_element(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.Dict) and node.keys:
            targets.append(node)
        elif isinstance(node, ast.List) and node.elts:
            targets.append(node)
    for node in targets:
        if isinstance(node, ast.Dict):
            node.keys = node.keys[1:]
            node.values = node.values[1:]
        else:
            node.elts = node.elts[1:]
    return bool(targets)


def _apply_range_bound_shift(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "range"
            and node.args
        )
    ]
    for node in targets:
        last = node.args[-1]
        node.args[-1] = ast.BinOp(left=last, op=ast.Add(), right=ast.Constant(value=1))
    return bool(targets)


def _own_returns(node):
    """The return statements that belong to one function body.

    The walk descends through the statements of the body and
    stops at any nested function or class, because a return
    inside one of those belongs to that nested scope and is
    judged against its own parameter list when the walk of the
    whole tree reaches it.
    """
    found = []
    stack = list(node.body)
    while stack:
        current = stack.pop()
        if isinstance(
            current,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda),
        ):
            continue
        if isinstance(current, ast.Return):
            found.append(current)
        stack.extend(ast.iter_child_nodes(current))
    return found


def _apply_wrong_variable_returned(tree):
    targets = []
    planted = set()
    for node in _sorted_nodes(tree):
        if not isinstance(node, ast.FunctionDef):
            continue
        params = [arg.arg for arg in node.args.args]
        if len(params) < 2:
            continue
        for inner in _own_returns(node):
            if (
                isinstance(inner.value, ast.Name)
                and inner.value.id in params
                and id(inner) not in planted
            ):
                planted.add(id(inner))
                index = params.index(inner.value.id)
                targets.append((inner, params[(index + 1) % len(params)]))
    for inner, name in targets:
        inner.value.id = name
    return bool(targets)


_OPERAND_SWAP_OPS = (ast.Sub, ast.Div, ast.FloorDiv, ast.Mod)


def _apply_swapped_operand_order(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.BinOp) and isinstance(node.op, _OPERAND_SWAP_OPS)
    ]
    for node in targets:
        node.left, node.right = node.right, node.left
    return bool(targets)


def _apply_dropped_else(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.If) and node.orelse
    ]
    for node in targets:
        node.orelse = []
    return bool(targets)


def _apply_swapped_boolean_operator(tree):
    targets = [
        node for node in _sorted_nodes(tree) if isinstance(node, ast.BoolOp)
    ]
    for node in targets:
        node.op = ast.Or() if isinstance(node.op, ast.And) else ast.And()
    return bool(targets)


def _collect_awaits(tree):
    """The await expressions of a tree with their parents.

    Each entry carries the depth of the await, the parent node,
    the field the await sits in, the index inside that field when
    the field is a list, and the await node itself. The entries
    come back deepest first, so replacing an inner await inside
    its parent await never strands the inner planting on a node
    the outer planting already detached from the tree.
    """
    found = []

    def visit(node, depth):
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, ast.AST):
                        if isinstance(item, ast.Await):
                            found.append(
                                (depth + 1, node, field, index, item)
                            )
                        visit(item, depth + 1)
            elif isinstance(value, ast.AST):
                if isinstance(value, ast.Await):
                    found.append((depth + 1, node, field, None, value))
                visit(value, depth + 1)

    visit(tree, 0)
    found.sort(key=lambda entry: -entry[0])
    return found


def _apply_dropped_await(tree):
    targets = _collect_awaits(tree)
    for _depth, parent, field, index, node in targets:
        if index is None:
            setattr(parent, field, node.value)
        else:
            getattr(parent, field)[index] = node.value
    return bool(targets)


_BROAD_HANDLER_NAMES = ("Exception", "BaseException")


def _handler_type_name_list(handler_type):
    if isinstance(handler_type, ast.Name):
        return [handler_type.id]
    if isinstance(handler_type, ast.Tuple):
        return [
            member.id
            for member in handler_type.elts
            if isinstance(member, ast.Name)
        ]
    return []


def _handler_type_names(handler_type):
    return set(_handler_type_name_list(handler_type))


def _raise_type_name(node):
    if (
        isinstance(node, ast.Raise)
        and isinstance(node.exc, ast.Call)
        and isinstance(node.exc.func, ast.Name)
        and node.exc.func.id[:1].isupper()
    ):
        return node.exc.func.id
    return None


def _module_exception_names(tree):
    names = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.ExceptHandler) and node.type is not None:
            found = _handler_type_name_list(node.type)
        elif _raise_type_name(node) is not None:
            found = [_raise_type_name(node)]
        else:
            continue
        for name in found:
            if name not in names:
                names.append(name)
    return names


def _apply_swapped_raised_error(tree):
    names = _module_exception_names(tree)
    targets = []
    for node in _sorted_nodes(tree):
        if _raise_type_name(node) is None:
            continue
        raised = node.exc.func.id
        for name in names:
            if name != raised:
                targets.append((node.exc.func, name))
                break
    for func, replacement in targets:
        func.id = replacement
    return bool(targets)


def _apply_widened_exception_handler(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if not isinstance(node, ast.ExceptHandler):
            continue
        if node.type is None:
            continue
        if _handler_type_names(node.type) & set(_BROAD_HANDLER_NAMES):
            continue
        targets.append(node)
    for node in targets:
        node.type = ast.Name(id="Exception", ctx=ast.Load())
    return bool(targets)


def _apply_swapped_dictionary_entry(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Dict)
        and any(key is not None for key in node.keys)
    ]
    for node in targets:
        pairs = [
            (key, value) if key is None else (value, key)
            for key, value in zip(node.keys, node.values)
        ]
        node.keys = [key for key, _value in pairs]
        node.values = [value for _key, value in pairs]
    return bool(targets)


def _is_negation(node):
    return isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not)


def _apply_inverted_truth_test(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.While):
            targets.append(node)
        elif isinstance(node, (ast.If, ast.IfExp)) and _is_negation(
            node.test
        ):
            targets.append(node)
    for node in targets:
        if _is_negation(node.test):
            node.test = node.test.operand
        else:
            node.test = ast.UnaryOp(op=ast.Not(), operand=node.test)
    return bool(targets)


_COMPREHENSIONS = (
    ast.ListComp,
    ast.SetComp,
    ast.DictComp,
    ast.GeneratorExp,
)


def _bound_names_in_scope(scope):
    """The names one scope binds, parameters first, then source order.

    The walk reads the body of the scope and stops at any nested
    function or class, because a name bound in a nested scope is
    not bound in this one, and it never descends into a
    comprehension, because a name bound only inside a comprehension
    is not bound in this scope either. A function or class defined
    in the body binds its own name in this scope.
    """
    found = []

    def note(position, name):
        found.append((position, name))

    if isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef)):
        args = scope.args
        params = [
            arg.arg for arg in (*args.posonlyargs, *args.args)
        ]
        if args.vararg is not None:
            params.append(args.vararg.arg)
        params.extend(arg.arg for arg in args.kwonlyargs)
        if args.kwarg is not None:
            params.append(args.kwarg.arg)
        for index, name in enumerate(params):
            note((0, 0, index), name)
    stack = list(scope.body)
    while stack:
        current = stack.pop()
        if isinstance(
            current, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
        ):
            note((current.lineno, current.col_offset, 0), current.name)
            continue
        if isinstance(current, (ast.Lambda, *_COMPREHENSIONS)):
            continue
        if isinstance(current, ast.Name) and isinstance(
            current.ctx, ast.Store
        ):
            note((current.lineno, current.col_offset, 0), current.id)
        elif isinstance(current, ast.Import):
            for index, alias in enumerate(current.names):
                note(
                    (current.lineno, current.col_offset, index),
                    alias.asname or alias.name.split(".")[0],
                )
        elif isinstance(current, ast.ImportFrom):
            for index, alias in enumerate(current.names):
                note(
                    (current.lineno, current.col_offset, index),
                    alias.asname or alias.name,
                )
        elif isinstance(current, ast.ExceptHandler) and current.name:
            note((current.lineno, current.col_offset, 0), current.name)
        stack.extend(ast.iter_child_nodes(current))
    names = []
    for _position, name in sorted(found):
        if name not in names:
            names.append(name)
    return names


def _collect_loop_retargets(tree):
    """The for loops of a tree with the name each one is pointed at.

    Each entry carries the loop node and the first name bound in
    the scope that encloses the loop other than the name the loop
    already targets, and a loop whose scope binds no other name
    earns no entry. The entries are collected from the tree as
    parsed, before any loop is pointed anywhere.
    """
    found = []

    def visit(node, scope):
        if isinstance(
            node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
        ):
            scope = node
        if isinstance(node, (ast.For, ast.AsyncFor)) and isinstance(
            node.target, ast.Name
        ):
            for name in _bound_names_in_scope(scope):
                if name != node.target.id:
                    found.append((node, name))
                    break
        for child in ast.iter_child_nodes(node):
            visit(child, scope)

    visit(tree, tree)
    return found


def _apply_reassigned_loop_variable(tree):
    targets = _collect_loop_retargets(tree)
    for node, name in targets:
        node.target = ast.Name(id=name, ctx=ast.Store())
    return bool(targets)


def _apply_swapped_call_argument_order(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Call) and len(node.args) >= 2
    ]
    for node in targets:
        node.args[0], node.args[1] = node.args[1], node.args[0]
    return bool(targets)


_VERSION_NAMES = ("VERSION", "__version__", "version")


def _out_of_scope_string_ids(tree):
    """The ids of the string constants seed-21 never plants.

    A docstring is the first statement of a module or function or
    class body when that statement is a bare string expression, and
    it is documentation rather than behaviour. The literal a
    version assignment carries whole belongs to seed-00, which
    replaces it entire. Both shapes are gathered here so the apply
    function can read only the constants that stand anywhere else.
    """
    excluded = set()
    for node in ast.walk(tree):
        if isinstance(
            node,
            (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef),
        ):
            if (
                node.body
                and isinstance(node.body[0], ast.Expr)
                and isinstance(node.body[0].value, ast.Constant)
                and isinstance(node.body[0].value.value, str)
            ):
                excluded.add(id(node.body[0].value))
        value = None
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Constant):
            if any(
                isinstance(target, ast.Name) and target.id in _VERSION_NAMES
                for target in node.targets
            ):
                value = node.value
        if isinstance(node, ast.AnnAssign) and isinstance(node.value, ast.Constant):
            if isinstance(node.target, ast.Name) and node.target.id in _VERSION_NAMES:
                value = node.value
        if value is not None and isinstance(value.value, str):
            excluded.add(id(value))
    return excluded


def _apply_altered_string_literal(tree):
    excluded = _out_of_scope_string_ids(tree)
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Constant)
        and isinstance(node.value, str)
        and node.value
        and id(node) not in excluded
    ]
    for node in targets:
        first = node.value[0]
        node.value = ("z" if first == "x" else "x") + node.value[1:]
    return bool(targets)


def _collect_negations(tree):
    """The unary minus expressions of a tree with their parents.

    Each entry carries the depth of the negation, the parent node,
    the field the negation sits in, the index inside that field
    when the field is a list, and the negation node itself. The
    entries come back deepest first, so removing an inner negation
    inside its parent negation never strands the inner planting on
    a node the outer planting already detached from the tree. The
    collection mirrors the one the dropped await seed uses.
    """
    found = []

    def is_negation(node):
        return isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub)

    def visit(node, depth):
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, ast.AST):
                        if is_negation(item):
                            found.append((depth + 1, node, field, index, item))
                        visit(item, depth + 1)
            elif isinstance(value, ast.AST):
                if is_negation(value):
                    found.append((depth + 1, node, field, None, value))
                visit(value, depth + 1)

    visit(tree, 0)
    found.sort(key=lambda entry: -entry[0])
    return found


def _apply_dropped_numeric_negation(tree):
    targets = _collect_negations(tree)
    for _depth, parent, field, index, node in targets:
        if index is None:
            setattr(parent, field, node.operand)
        else:
            getattr(parent, field)[index] = node.operand
    return bool(targets)


def _collect_loop_breaks(tree):
    """The break statements standing in the body of a loop.

    Each entry carries the parent node, the field the break sits
    in, the index inside that field when the field is a list, and
    the break node itself. The walk turns its inside a loop
    reading on for the body of a for or while loop and off again
    for the else clause of the loop, and it never carries the
    reading across a function or class or lambda boundary, because
    a break inside one of those does not belong to the loop
    around it.
    """
    found = []

    def visit(node, parent, field, index, inside_loop_body):
        if isinstance(
            node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)
        ):
            inside_loop_body = False
        if isinstance(node, ast.Break) and inside_loop_body:
            found.append((parent, field, index, node))
        if isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
            for position, statement in enumerate(node.body):
                visit(statement, node, "body", position, True)
            for position, statement in enumerate(node.orelse):
                visit(statement, node, "orelse", position, False)
            return
        for child_field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for position, item in enumerate(value):
                    if isinstance(item, ast.AST):
                        visit(item, node, child_field, position, inside_loop_body)
            elif isinstance(value, ast.AST):
                visit(value, node, child_field, None, inside_loop_body)

    visit(tree, None, None, None, False)
    return found


def _apply_swapped_loop_control(tree):
    targets = _collect_loop_breaks(tree)
    for parent, field, index, _node in targets:
        replacement = ast.Continue()
        if index is None:
            setattr(parent, field, replacement)
        else:
            getattr(parent, field)[index] = replacement
    return bool(targets)


def _apply_swapped_augmented_operator(tree):
    targets = [
        (node, _ARITHMETIC_SWAPS[type(node.op)])
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.AugAssign)
        and type(node.op) in _ARITHMETIC_SWAPS
    ]
    for node, replacement in targets:
        node.op = replacement()
    return bool(targets)


_IDENTITY_TO_EQUALITY = {ast.Is: ast.Eq, ast.IsNot: ast.NotEq}


def _apply_identity_comparison_as_equality(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.Compare) and node.ops:
            swapped = _IDENTITY_TO_EQUALITY.get(type(node.ops[0]))
            if swapped is not None:
                targets.append((node, swapped))
    for node, swapped in targets:
        node.ops[0] = swapped()
    return bool(targets)


def _apply_subscript_index_shift(tree):
    targets = [
        node.slice
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Subscript) and _is_int_constant(node.slice)
    ]
    for target in targets:
        target.value = target.value + 1
    return bool(targets)


def _apply_swapped_keyword_argument_values(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if not isinstance(node, ast.Call):
            continue
        named = [
            keyword for keyword in node.keywords if keyword.arg is not None
        ]
        if len(named) >= 2:
            targets.append((named[0], named[1]))
    for first, second in targets:
        first.value, second.value = second.value, first.value
    return bool(targets)


def _apply_slice_stop_shift(tree):
    targets = [
        node.upper
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Slice) and _is_int_constant(node.upper)
    ]
    for target in targets:
        target.value = target.value + 1
    return bool(targets)


def _apply_shifted_numeric_default(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            for default in (*node.args.defaults, *node.args.kw_defaults):
                if _is_int_constant(default):
                    targets.append(default)
    for target in targets:
        target.value = target.value + 1
    return bool(targets)


_NESTED_SCOPE_TYPES = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)


def _scope_parameter_names(scope):
    if not isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
        return set()
    arguments = scope.args
    names = {argument.arg for argument in (*arguments.posonlyargs, *arguments.args)}
    if arguments.vararg is not None:
        names.add(arguments.vararg.arg)
    names.update(argument.arg for argument in arguments.kwonlyargs)
    if arguments.kwarg is not None:
        names.add(arguments.kwarg.arg)
    return names


def _collect_sibling_attribute_swaps(tree):
    records = []

    def new_record(scope):
        record = {
            "parameters": _scope_parameter_names(scope),
            "stores": {},
            "loads": [],
        }
        records.append(record)
        return record

    def header_children(node):
        children = list(node.decorator_list) if not isinstance(node, ast.Lambda) else []
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            children.append(node.args)
            if node.returns is not None:
                children.append(node.returns)
            return children, list(node.body)
        if isinstance(node, ast.ClassDef):
            children.extend(node.bases)
            children.extend(node.keywords)
            return children, list(node.body)
        return [node.args], [node.body]

    def visit(node, record):
        if isinstance(node, _NESTED_SCOPE_TYPES):
            headers, body = header_children(node)
            for child in headers:
                visit(child, record)
            record = new_record(node)
            for child in body:
                visit(child, record)
            return
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            record["stores"][node.id] = record["stores"].get(node.id, 0) + 1
        if (
            isinstance(node, ast.Attribute)
            and isinstance(node.ctx, ast.Load)
            and isinstance(node.value, ast.Name)
        ):
            record["loads"].append(node)
        for child in ast.iter_child_nodes(node):
            visit(child, record)

    visit(tree, new_record(tree))
    targets = []
    for record in records:
        loads_by_base = {}
        for load in record["loads"]:
            loads_by_base.setdefault(load.value.id, []).append(load)
        for base, loads in loads_by_base.items():
            store_count = record["stores"].get(base, 0)
            if base in record["parameters"]:
                if store_count != 0:
                    continue
            elif store_count != 1:
                continue
            distinct = []
            for load in sorted(loads, key=lambda node: (node.lineno, node.col_offset)):
                if load.attr not in distinct:
                    distinct.append(load.attr)
            if len(distinct) < 2:
                continue
            targets.extend(
                (load, distinct[1]) for load in loads if load.attr == distinct[0]
            )
    return targets


def _apply_swapped_sibling_attribute(tree):
    targets = _collect_sibling_attribute_swaps(tree)
    for load, replacement in targets:
        load.attr = replacement
    return bool(targets)


def _specific_raise_names(try_node):
    """The specific exception type names one try body raises.

    The walk reads the statements of the try body and stops at
    any nested function or class or lambda, because a raise
    inside one of those belongs to that nested scope and never
    propagates through this try statement when the body runs. A
    counted raise is the shape _raise_type_name reads, and a
    raise of the broad base itself never serves as a name here.
    Each name is gathered once, at the place it first stands.
    """
    names = []

    def visit(node):
        if isinstance(
            node,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda),
        ):
            return
        name = _raise_type_name(node)
        if (
            name is not None
            and name not in _BROAD_HANDLER_NAMES
            and name not in names
        ):
            names.append(name)
        for child in ast.iter_child_nodes(node):
            visit(child)

    for statement in try_node.body:
        visit(statement)
    return names


def _apply_narrowed_exception_handler(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if not isinstance(node, (ast.Try, ast.TryStar)):
            continue
        specific = _specific_raise_names(node)
        if not specific:
            continue
        for handler in node.handlers:
            if handler.type is None:
                continue
            if not (
                _handler_type_names(handler.type)
                & set(_BROAD_HANDLER_NAMES)
            ):
                continue
            targets.append((handler, specific[0]))
    for handler, replacement in targets:
        handler.type = ast.Name(id=replacement, ctx=ast.Load())
    return bool(targets)


def _apply_swapped_parameter_defaults(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(
            node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)
        ):
            holders = [
                (node.args.defaults, index)
                for index in range(len(node.args.defaults))
            ]
            holders.extend(
                (node.args.kw_defaults, index)
                for index, default in enumerate(node.args.kw_defaults)
                if default is not None
            )
            if len(holders) >= 2:
                targets.append((holders[0], holders[1]))
    for (first_list, first_index), (second_list, second_index) in targets:
        first_list[first_index], second_list[second_index] = (
            second_list[second_index],
            first_list[first_index],
