def _apply_dropped_finally_body(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, (ast.Try, ast.TryStar)) and node.finalbody
    ]
    for node in targets:
        if node.handlers:
            node.finalbody = []
        else:
            node.finalbody = [ast.Pass()]
    return bool(targets)


def _apply_dropped_decorator(tree):
