        node
        for node in _sorted_nodes(tree)
        if isinstance(
            node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
        )
        and node.decorator_list
    ]
    for node in targets:
        node.decorator_list = node.decorator_list[1:]
