def _collect_yields(tree):
    """The yield expressions of a tree with their parents.

    Each entry carries the depth of the yield, the parent node,
    the field the yield sits in, the index inside that field when
    the field is a list, and the yield node itself. The entries
    come back deepest first, so replacing an inner yield inside
    its parent yield never strands the inner planting on a node
    the outer planting already detached from the tree. The
    collection mirrors the one the dropped await seed uses. A
    yield from is a different node and is never collected,
    because it delegates the whole iteration to another iterable
    rather than producing one item itself.
    """
    found = []

    def visit(node, depth):
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, ast.AST):
                        if isinstance(item, ast.Yield):
                            found.append(
                                (depth + 1, node, field, index, item)
                            )
                        visit(item, depth + 1)
            elif isinstance(value, ast.AST):
                if isinstance(value, ast.Yield):
                    found.append((depth + 1, node, field, None, value))
                visit(value, depth + 1)

    visit(tree, 0)
    found.sort(key=lambda entry: -entry[0])
    return found


def _apply_dropped_yield(tree):
    targets = _collect_yields(tree)
    for _depth, parent, field, index, node in targets:
        replacement = (
            node.value
            if node.value is not None
            else ast.Constant(value=None)
        )
        if index is None:
            setattr(parent, field, replacement)
        else:
            getattr(parent, field)[index] = replacement
    return bool(targets)


def _apply_dropped_condition_term(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.BoolOp) and len(node.values) >= 2
    ]
    for node in targets:
        node.values = node.values[:-1]
    return bool(targets)


def _apply_dropped_base_class(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.ClassDef) and node.bases
    ]
    for node in targets:
        node.bases = node.bases[1:]
    return bool(targets)


def _apply_slice_start_shift(tree):
    targets = [
        node.lower
        for node in _sorted_nodes(tree)
        if isinstance(node, ast.Slice) and _is_int_constant(node.lower)
    ]
    for target in targets:
        target.value = target.value + 1
    return bool(targets)


def _collect_loop_continues(tree):
    """The continue statements standing in the body of a loop.

    Each entry carries the parent node, the field the continue
    sits in, the index inside that field when the field is a
    list, and the continue node itself. The walk turns its
    inside a loop reading on for the body of a for or while
    loop and off again for the else clause of the loop, and it
    never carries the reading across a function or class or
    lambda boundary, because a continue inside one of those
    does not belong to the loop around it. The collection
    mirrors the one the swapped loop control seed uses for
    its break statements.
    """
    found = []

    def visit(node, parent, field, index, inside_loop_body):
        if isinstance(
            node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)
        ):
            inside_loop_body = False
        if isinstance(node, ast.Continue) and inside_loop_body:
            found.append((parent, field, index, node))
        if isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
            for position, statement in enumerate(node.body):
                visit(statement, node, "body", position, True)
            for position, statement in enumerate(node.orelse):
                visit(statement, node, "orelse", position, False)
            return
        for child_field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for position, item in enumerate(value):
                    if isinstance(item, ast.AST):
                        visit(item, node, child_field, position, inside_loop_body)
            elif isinstance(value, ast.AST):
                visit(value, node, child_field, None, inside_loop_body)

    visit(tree, None, None, None, False)
    return found


def _apply_reversed_loop_control(tree):
    targets = _collect_loop_continues(tree)
    for parent, field, index, _node in targets:
        replacement = ast.Break()
        if index is None:
            setattr(parent, field, replacement)
        else:
            getattr(parent, field)[index] = replacement
    return bool(targets)


def _collect_scope_declarations(tree):
    """The global and nonlocal statements of a tree with their parents.

    Each entry carries the parent node, the field the statement
    sits in, the index inside that field, and the statement
    itself. A declaration is a statement and stands in a
    statement list, so only list fields earn entries, and the
    entries for one list let the apply function judge that list
    as a whole before it removes anything from it.
    """
    found = []

    def visit(node):
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, (ast.Global, ast.Nonlocal)):
                        found.append((node, field, index, item))
                    if isinstance(item, ast.AST):
                        visit(item)
            elif isinstance(value, ast.AST):
                visit(value)

    visit(tree)
    return found


def _apply_dropped_scope_declaration(tree):
    targets = _collect_scope_declarations(tree)
    lists = {}
    for parent, field, index, _node in targets:
        key = (id(parent), field)
        if key not in lists:
            lists[key] = (parent, field, [])
        lists[key][2].append(index)
    planted = False
    for parent, field, indices in lists.values():
        statements = getattr(parent, field)
        if all(
            isinstance(statement, (ast.Global, ast.Nonlocal))
            for statement in statements
        ):
            continue
        for index in sorted(indices, reverse=True):
            del statements[index]
        planted = True
    return planted


def _apply_swapped_assignment_values(tree):
    targets = []
    for node in _sorted_nodes(tree):
        value = None
        if isinstance(node, ast.Assign):
            value = node.value
        elif isinstance(node, ast.AnnAssign):
            value = node.value
        if isinstance(value, ast.Tuple) and len(value.elts) >= 2:
            targets.append(value)
    for value in targets:
        value.elts[0], value.elts[1] = value.elts[1], value.elts[0]
    return bool(targets)


def _apply_dropped_loop_else(tree):
    targets = [
        node
        for node in _sorted_nodes(tree)
        if isinstance(node, (ast.For, ast.AsyncFor, ast.While)) and node.orelse
    ]
    for node in targets:
        node.orelse = []
    return bool(targets)


def _apply_dropped_keyword_argument(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if isinstance(node, ast.Call):
            named = [kw for kw in node.keywords if kw.arg is not None]
            if named:
                targets.append((node, named[0]))
    for node, keyword in targets:
        node.keywords.remove(keyword)
    return bool(targets)


def _apply_flipped_range_step(tree):
    targets = []
    for node in _sorted_nodes(tree):
        if not (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "range"
            and len(node.args) == 3
        ):
            continue
        step = node.args[2]
        if isinstance(step, ast.Starred):
            continue
        if isinstance(step, ast.UnaryOp) and isinstance(step.op, ast.USub):
            continue
        if isinstance(step, ast.Constant) and isinstance(step.value, bool):
            continue
        if _is_zero_literal(step):
            continue
        targets.append(node)
    for node in targets:
        step = node.args[2]
        if _is_int_constant(step):
            node.args[2] = ast.Constant(value=-step.value)
        else:
            node.args[2] = ast.UnaryOp(op=ast.USub(), operand=step)
    return bool(targets)


_TEST_HOLDERS = (ast.If, ast.While, ast.IfExp)


def _collect_outer_negations(tree):
    """The logical negations of a tree standing outside a condition test.

    Each entry carries the depth of the negation, the parent node,
    the field the negation sits in, the index inside that field when
    the field is a list, and the negation node itself. The entries
    come back deepest first, so stripping an inner negation inside
    its parent negation never strands the inner planting on a node
    the outer planting already detached from the tree. A negation
    standing anywhere inside the test expression of an if statement
    or a while loop or a conditional expression is never collected,
    and the exclusion follows the test into everything it carries.
    The guard of a match case is a condition test in the same sense,
    so a negation standing anywhere inside a guard is never
    collected either.
    """
    found = []

    def visit(node, depth, in_test):
        for field, value in ast.iter_fields(node):
            child_in_test = in_test or (
                field == "test" and isinstance(node, _TEST_HOLDERS)
            ) or (
                field == "guard" and isinstance(node, ast.match_case)
            )
            if isinstance(value, list):
                for index, item in enumerate(value):
                    if isinstance(item, ast.AST):
                        if (
                            isinstance(item, ast.UnaryOp)
                            and isinstance(item.op, ast.Not)
                            and not child_in_test
                        ):
                            found.append(
                                (depth + 1, node, field, index, item)
                            )
                        visit(item, depth + 1, child_in_test)
            elif isinstance(value, ast.AST):
                if (
                    isinstance(value, ast.UnaryOp)
                    and isinstance(value.op, ast.Not)
                    and not child_in_test
                ):
                    found.append((depth + 1, node, field, None, value))
                visit(value, depth + 1, child_in_test)

    visit(tree, 0, False)
    found.sort(key=lambda entry: -entry[0])
    return found


def _apply_dropped_logical_negation(tree):
    targets = _collect_outer_negations(tree)
    for _depth, parent, field, index, node in targets:
        if index is None:
            setattr(parent, field, node.operand)
        else:
            getattr(parent, field)[index] = node.operand
    return bool(targets)


